Q exec_q_free_create (UInt8 exec_q_free_size)
{	
	UInt8 n ;

	Q exec_q_free = q_create () ;

	for (n = 0 ; n < exec_q_free_size ; n++)
	{
		if( exec_q_free )
		{
			exec_q_free_add(exec_q_free , sizeof( Exec_Q_Msg) ) ; 
		}
	}

	return exec_q_free ;
}

